var Rr = p.res * 1000, Cc = p.cap * 1e-6, E = p.emf;
var tau = Rr * Cc;
var padL = 44, padR = 58, padT = 18, padB = 28;
var T = 5 * tau;
var PW = W - padL - padR, PH = H - padT - padB;
var X = function (s) { return padL + (s / T) * PW; };
var Y = function (f) { return padT + PH - f * PH; };

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + PH); ctx.lineTo(padL + PW, padT + PH);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// tau gridlines
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
for (var k = 1; k <= 5; k++) {
  ctx.beginPath(); ctx.moveTo(X(k * tau), padT); ctx.lineTo(X(k * tau), padT + PH); ctx.stroke();
}
ctx.beginPath(); ctx.moveTo(padL, Y(0.632)); ctx.lineTo(padL + PW, Y(0.632)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.faint;
ctx.textAlign = "center";
for (var k2 = 1; k2 <= 5; k2++) {
  ctx.fillText(k2 + "T", X(k2 * tau), padT + PH + 15);
}
ctx.textAlign = "right";
ctx.fillText("63%", padL - 5, Y(0.632) + 4);
ctx.fillText("0", padL - 5, padT + PH + 4);
ctx.fillText("100%", padL - 5, padT + 10);
ctx.textAlign = "left";
ctx.fillText("time, in units of one time constant T", padL, padT + 10);

// voltage curve
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var s = T * i / 200;
  var v = 1 - Math.exp(-s / tau);
  if (i === 0) { ctx.moveTo(X(s), Y(v)); } else { ctx.lineTo(X(s), Y(v)); }
}
ctx.stroke();

// current curve
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.setLineDash([5, 4]);
ctx.beginPath();
for (var j = 0; j <= 200; j++) {
  var s2 = T * j / 200;
  var cu = Math.exp(-s2 / tau);
  if (j === 0) { ctx.moveTo(X(s2), Y(cu)); } else { ctx.lineTo(X(s2), Y(cu)); }
}
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.fillText("capacitor voltage", padL + PW + 6, Y(0.9));
ctx.fillStyle = C.figure;
ctx.fillText("current", padL + PW + 6, Y(0.12));

// moving marker
var cur = ((t % 6) / 6) * T;
var vf = 1 - Math.exp(-cur / tau);
var cf = Math.exp(-cur / tau);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(cur), padT); ctx.lineTo(X(cur), padT + PH); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(cur), Y(vf), 4.5, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(cur), Y(cf), 4.5, 0, Math.PI * 2); ctx.fill();

var volts = E * vf;
var milli = (E / Rr) * cf * 1000;
out.note = "T = RC = " + tau.toFixed(3) + " s; at t = " + cur.toFixed(2) + " s the capacitor is at " +
  volts.toFixed(2) + " V of " + E.toFixed(0) + " V and the current is " + milli.toFixed(3) + " mA";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
var pw = W / 3;

var panel = function (x0, mode, title, sub) {
  var L = x0 + 0.16 * pw, Rt = x0 + 0.84 * pw;
  var Tp = 44, Bt = H - 34;
  ctx.strokeStyle = C.ink;

  // top wire with resistor gap
  var ra = (L + Rt) / 2 - 16, rb = (L + Rt) / 2 + 16;
  ctx.beginPath();
  ctx.moveTo(L, Tp); ctx.lineTo(ra, Tp);
  ctx.moveTo(rb, Tp); ctx.lineTo(Rt, Tp);
  ctx.stroke();
  ctx.strokeRect(ra, Tp - 7, rb - ra, 14);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText("R", (ra + rb) / 2, Tp - 13);

  // bottom wire
  ctx.beginPath(); ctx.moveTo(L, Bt); ctx.lineTo(Rt, Bt); ctx.stroke();

  // left side: battery
  var by = (Tp + Bt) / 2;
  ctx.beginPath();
  ctx.moveTo(L, Tp); ctx.lineTo(L, by - 9);
  ctx.moveTo(L, by + 9); ctx.lineTo(L, Bt);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(L - 13, by - 9); ctx.lineTo(L + 13, by - 9);
  ctx.moveTo(L - 7, by + 9); ctx.lineTo(L + 7, by + 9);
  ctx.stroke();
  ctx.textAlign = "right";
  ctx.fillText("E", L - 17, by + 4);

  // right side: the capacitor or its replacement
  ctx.textAlign = "left";
  if (mode === 0) {
    ctx.beginPath();
    ctx.moveTo(Rt, Tp); ctx.lineTo(Rt, by - 7);
    ctx.moveTo(Rt, by + 7); ctx.lineTo(Rt, Bt);
    ctx.stroke();
    ctx.strokeStyle = C.accent;
    ctx.beginPath();
    ctx.moveTo(Rt - 13, by - 7); ctx.lineTo(Rt + 13, by - 7);
    ctx.moveTo(Rt - 13, by + 7); ctx.lineTo(Rt + 13, by + 7);
    ctx.stroke();
    ctx.fillStyle = C.accent;
    ctx.fillText("C", Rt + 17, by + 4);
  } else if (mode === 1) {
    ctx.strokeStyle = C.accent;
    ctx.beginPath(); ctx.moveTo(Rt, Tp); ctx.lineTo(Rt, Bt); ctx.stroke();
    ctx.fillStyle = C.accent;
    ctx.fillText("wire", Rt + 8, by + 4);
  } else {
    ctx.strokeStyle = C.ink;
    ctx.beginPath();
    ctx.moveTo(Rt, Tp); ctx.lineTo(Rt, by - 12);
    ctx.moveTo(Rt, by + 12); ctx.lineTo(Rt, Bt);
    ctx.stroke();
    ctx.fillStyle = C.accent;
    ctx.fillText("gap", Rt + 8, by + 4);
  }

  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(title, x0 + pw / 2, 20);
  ctx.fillStyle = C.faint;
  ctx.fillText(sub, x0 + pw / 2, H - 12);
  ctx.strokeStyle = C.ink;
};

panel(0, 0, "the circuit", "switch closes at t = 0");
panel(pw, 1, "just after, t = 0+", "current is E over R");
panel(2 * pw, 2, "long after", "current is zero");

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(pw, 8); ctx.lineTo(pw, H - 22);
ctx.moveTo(2 * pw, 8); ctx.lineTo(2 * pw, H - 22);
ctx.stroke();
ctx.setLineDash([]);

out.note = "an uncharged capacitor starts as a wire and ends as a gap";

var R1 = p.r1 * 1000, R2 = p.r2 * 1000, Cc = p.cap * 1e-6, E = 12;
var Vf = E * R2 / (R1 + R2);
var Rth = R1 * R2 / (R1 + R2);
var tau = Rth * Cc;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
ctx.strokeStyle = C.ink;
ctx.fillStyle = C.ink;

var L = 0.16 * W, M = 0.52 * W, Rt = 0.82 * W;
var Tp = 34, Bt = H - 34, Ay = (Tp + Bt) / 2;

// top rail from battery to node A branch
ctx.beginPath();
ctx.moveTo(L, Tp); ctx.lineTo(M, Tp);
ctx.moveTo(L, Bt); ctx.lineTo(Rt, Bt);
ctx.stroke();

// battery on the left
var by = (Tp + Bt) / 2;
ctx.beginPath();
ctx.moveTo(L, Tp); ctx.lineTo(L, by - 9);
ctx.moveTo(L, by + 9); ctx.lineTo(L, Bt);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(L - 13, by - 9); ctx.lineTo(L + 13, by - 9);
ctx.moveTo(L - 7, by + 9); ctx.lineTo(L + 7, by + 9);
ctx.stroke();
ctx.textAlign = "right";
ctx.fillText("12 V", L - 17, by + 4);

// R1 from top rail down to node A
var r1a = Tp + 14, r1b = Ay - 14;
ctx.beginPath();
ctx.moveTo(M, Tp); ctx.lineTo(M, r1a);
ctx.moveTo(M, r1b); ctx.lineTo(M, Ay);
ctx.stroke();
ctx.strokeRect(M - 7, r1a, 14, r1b - r1a);
ctx.textAlign = "left";
ctx.fillText("R1 = " + p.r1.toFixed(1) + " k", M + 12, (r1a + r1b) / 2 + 4);

// R2 from node A down to the bottom rail
var r2a = Ay + 14, r2b = Bt - 14;
ctx.beginPath();
ctx.moveTo(M, Ay); ctx.lineTo(M, r2a);
ctx.moveTo(M, r2b); ctx.lineTo(M, Bt);
ctx.stroke();
ctx.strokeRect(M - 7, r2a, 14, r2b - r2a);
ctx.fillText("R2 = " + p.r2.toFixed(1) + " k", M + 12, (r2a + r2b) / 2 + 4);

// node A and the wire across to the capacitor branch
ctx.beginPath(); ctx.arc(M, Ay, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("A", M - 18, Ay - 6);
ctx.beginPath(); ctx.moveTo(M, Ay); ctx.lineTo(Rt, Ay); ctx.stroke();

// capacitor from that wire down to the bottom rail
ctx.beginPath();
ctx.moveTo(Rt, Ay); ctx.lineTo(Rt, Ay + 22);
ctx.moveTo(Rt, Ay + 36); ctx.lineTo(Rt, Bt);
ctx.stroke();
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(Rt - 13, Ay + 22); ctx.lineTo(Rt + 13, Ay + 22);
ctx.moveTo(Rt - 13, Ay + 36); ctx.lineTo(Rt + 13, Ay + 36);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("C = " + p.cap.toFixed(0) + " uF", Rt - 10, Ay + 56);

// fill bar showing how charged it is
var frac = 1 - Math.exp(-((t % 6) / 6) * 5);
ctx.fillStyle = C.figure;
ctx.fillRect(Rt - 13, Ay + 24, 26 * frac, 10);
ctx.strokeStyle = C.rule;
ctx.strokeRect(Rt - 13, Ay + 24, 26, 10);

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("kill the battery and R1 sits in parallel with R2 across C", 8, H - 10);

out.note = "final voltage " + Vf.toFixed(2) + " V, R seen by C = " + (Rth / 1000).toFixed(3) +
  " k, T = " + tau.toFixed(4) + " s, now at " + (Vf * frac).toFixed(2) + " V";
